fn takes_and_returns(s: String) -> String {
    println!("函数里拿到：{}", s);
    s
}

fn main() {
    let x = 42;
    let y = x;
    println!("Copy: x = {}, y = {}", x, y);

    let s1 = String::from("hello");
    let s2 = s1;
    // println!("{}", s1); // 取消注释会报 E0382：s1 已被 move
    println!("move 后：s2 = {}", s2);

    let s3 = String::from("hello");
    let s4 = s3.clone();
    println!("clone 后：s3 = {}, s4 = {}", s3, s4);

    let s5 = String::from("world");
    let s6 = takes_and_returns(s5);
    println!("拿回所有权后：s6 = {}", s6);

    {
        let s7 = String::from("临时");
        println!("作用域内：{}", s7);
    }
    println!("作用域已结束，s7 不可用（也不用 free）");
}

fn len_of(s: &str) -> usize {
    s.len()
}

fn append_exclaim(s: &mut String) {
    s.push('!');
}

fn main() {
    // 1. 不可变借用：可以同时有多个
    let s1 = String::from("hello");
    let r1 = &s1;
    let r2 = &s1;
    println!(
        "不可变借用：r1 = {}, r2 = {}, len = {}",
        r1,
        r2,
        len_of(&s1)
    );

    // 2. 可变借用：同一时刻只能有一个，且不能与不可变借用共存
    let mut s2 = String::from("rust");
    append_exclaim(&mut s2);
    println!("可变借用改完后：{}", s2);

    // 3. NLL：借用的作用域到最后一次使用为止，不是到花括号为止
    let mut s3 = String::from("borrow");
    let r3 = &s3;
    println!("先用不可变借用：{}", r3);
    // r3 在这里之后不再被使用，它的借用已经结束，
    // 所以下面再拿可变借用是合法的
    let r4 = &mut s3;
    r4.push('!');
    println!("借用结束后可再借可变：{}", s3);

    // 4. 借用不拥有数据：函数结束，借用结束，原变量还在
    let s4 = String::from("still mine");
    let n = len_of(&s4);
    println!("借出后原变量还在：{}（长度 {}）", s4, n);
}

fn first_word(s: &str) -> &str {
    let bytes = s.as_bytes();
    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[..i];
        }
    }
    s
}

fn greet(name: &str) {
    println!("你好，{}！", name);
}

fn sum_slice(nums: &[i32]) -> i32 {
    nums.iter().sum()
}

fn main() {
    // 1. String 是有所有权的堆上字符串，&str 是借来的视图
    let owned = String::from("hello world");
    let literal: &str = "hello world";
    println!("String：{}，&str 字面量：{}", owned, literal);
    // &String 会自动解引用强制转换成 &str，所以 greet 两种都能接
    greet(&owned);
    greet(literal);
    greet("直接传字面量也行");

    // 2. 切片：不复制，只记录起点和长度
    let word = first_word(&owned);
    println!("第一个词是：{}", word);
    // word 在这里之后不再被使用，它的借用已经结束，
    // 所以下面 clear 才是合法的（NLL，第 3 天的结论在这里又出现一次）
    let mut owned2 = owned;
    owned2.clear();
    println!("切片用完后才能 clear：'{}'", owned2);

    // 3. 数组和 Vec 的切片：函数参数写 &[i32]，比写 &Vec<i32> 更通用
    let nums = vec![10, 20, 30, 40, 50];
    println!("全部求和：{}", sum_slice(&nums));
    println!("中间一段求和：{}", sum_slice(&nums[1..4]));
    let arr = [1, 2, 3, 4];
    println!("数组切片求和：{}", sum_slice(&arr[..2]));

    // 4. 字符串切片按字节切，但必须落在字符边界上
    let cn = String::from("你好，世界");
    println!("字节长度：{}，字符个数：{}", cn.len(), cn.chars().count());
    println!("前一个汉字：{}", &cn[..3]);
    println!("去掉第一个汉字：{}", &cn[3..]);
}

use std::fmt;
use std::fs;

// 进程信息：字段全部是自有数据，struct 拥有它们，不借用临时字符串。
#[derive(Debug)]
struct ProcInfo {
    pid: u32,
    ppid: u32,
    name: String,
    state: char,
    threads: u32,
    vm_rss_kb: u64,
}

impl ProcInfo {
    // 关联函数：没有 self，像 C++ 的静态工厂函数，用 ProcInfo::load() 调用。
    fn load() -> Result<Self, String> {
        let text = fs::read_to_string("/proc/self/status")
            .map_err(|e| format!("读 /proc/self/status 失败：{e}"))?;
        Self::from_status(&text)
    }

    // 纯解析函数：输入是借用 &str，输出是自有 ProcInfo，所有权在这里交接。
    fn from_status(text: &str) -> Result<Self, String> {
        let mut name = String::new();
        let mut state = '?';
        let mut pid = 0;
        let mut ppid = 0;
        let mut threads = 0;
        let mut vm_rss_kb = 0;

        for line in text.lines() {
            // 每行形如 "Name:\tmyprog"，按冒号切一次，右边 trim。
            let Some((key, value)) = line.split_once(':') else {
                continue;
            };
            let value = value.trim();
            match key {
                "Name" => name = value.to_string(),
                "State" => state = value.chars().next().unwrap_or('?'),
                "Pid" => pid = value.parse().map_err(|_| "Pid 解析失败")?,
                "PPid" => ppid = value.parse().map_err(|_| "PPid 解析失败")?,
                "Threads" => threads = value.parse().map_err(|_| "Threads 解析失败")?,
                "VmRSS" => {
                    // "12345 kB"：先取数字部分再解析。
                    let num = value.split_whitespace().next().unwrap_or("0");
                    vm_rss_kb = num.parse().map_err(|_| "VmRSS 解析失败")?;
                }
                _ => {}
            }
        }
        if name.is_empty() || pid == 0 {
            return Err("status 里缺少 Name 或 Pid".to_string());
        }
        Ok(Self { pid, ppid, name, state, threads, vm_rss_kb })
    }

    // 方法：&self 只读借用，不拿走所有权，调用后 proc 还能继续用。
    fn summary(&self) -> String {
        format!(
            "{} (pid={}, ppid={}, state={}, threads={}, rss={:.1} MiB)",
            self.name, self.pid, self.ppid, self.state, self.threads,
            self.rss_mib()
        )
    }

    fn rss_mib(&self) -> f64 {
        self.vm_rss_kb as f64 / 1024.0
    }

    fn is_multithreaded(&self) -> bool {
        self.threads > 1
    }
}

impl fmt::Display for ProcInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.summary())
    }
}

fn main() {
    match ProcInfo::load() {
        Ok(proc) => {
            println!("{proc}");
            println!("多线程进程吗？{}", proc.is_multithreaded());
            // 结构体更新语法：只改一个字段，其余从原值 copy/move 过来。
            // 本例被替换的是 name 本身，其余字段全是 Copy 类型，所以 proc 仍可整体使用；
            // 若改的是 pid，name（String）会被 move 走，proc 就不能再整体使用。
            let renamed = ProcInfo { name: "renamed-demo".to_string(), ..proc };
            println!("改名后：{}", renamed.summary());
        }
        Err(e) => eprintln!("加载进程信息失败：{e}"),
    }

    // 一段写死的 status 文本，验证解析逻辑不依赖真实 /proc。
    let sample = "Name:\tdemo\nState:\tR (running)\nPid:\t1234\nPPid:\t100\nThreads:\t3\nVmRSS:\t20480 kB\n";
    let parsed = ProcInfo::from_status(sample).expect("示例文本应能解析");
    assert_eq!(parsed.pid, 1234);
    assert_eq!(parsed.threads, 3);
    println!("示例解析通过：{}", parsed.summary());
}

fn print_name(name: &str) {
    println!("name: {name}");
}

fn make_greeting(who: &str) -> String {
    format!("hello, {who}")
}

fn main() {
    // 1. move 的修法：不需要拿走所有权时，传 &str 借用，原值还能继续用。
    let name = String::from("demo-process");
    print_name(&name);
    println!("after borrow: {name}");

    // 2. 借用冲突的修法：把只读借用的使用收进一个块里，借用结束后再可变操作。
    let mut nums = vec![10, 20, 30];
    {
        let first = &nums[0];
        println!("first: {first}");
    } // first 的借用在这里结束
    nums.push(40);
    println!("after push: {nums:?}");

    // 3. 悬垂的修法：不能返回指向局部变量的引用，返回自有的 String。
    let owned = make_greeting("world");
    println!("{owned}");

    // 4. 先把需要的值复制出来，再做可变操作，也是一种缩短借用的办法。
    let mut scores = vec![80, 90];
    let first_score = scores[0]; // i32 是 Copy，复制出来就不欠借用
    scores.push(100);
    println!("first_score: {first_score}, scores: {scores:?}");
}

