/// 第一周验收：move、借用、切片、struct 各练一次，且一次通过 clippy。
struct ProcInfo {
    pid: u32,
    name: String,
}

impl ProcInfo {
    fn summary(&self) -> String {
        format!("{} ({})", self.name, self.pid)
    }

    fn rename(&mut self, new_name: &str) {
        self.name.clear();
        self.name.push_str(new_name);
    }
}

/// 返回第一个单词的切片：只借用，不拿所有权。
fn first_word(s: &str) -> &str {
    s.split_whitespace().next().unwrap_or("")
}

/// 对切片求和：参数是 &[i32]，调用方保留所有权。
fn total(scores: &[i32]) -> i32 {
    scores.iter().sum()
}

fn main() {
    // 1. move 与借用：summary 只借用，rename 可变借用，之后原值还能用。
    let mut proc = ProcInfo {
        pid: 1234,
        name: String::from("demo-process"),
    };
    println!("before: {}", proc.summary());
    proc.rename("renamed-process");
    println!("after: {}", proc.summary());

    // 2. 切片：first_word 返回 &str，借用活到最后一次使用为止。
    let line = String::from("hello rust world");
    let word = first_word(&line);
    println!("first word: {word}");
    println!("full line still usable: {line}");

    // 3. 借用结束后再改：块作用域收束只读借用，再 push。
    let mut nums = vec![10, 20, 30];
    {
        let first = &nums[0];
        println!("first: {first}");
    }
    nums.push(40);
    println!("total: {}, nums: {nums:?}", total(&nums));

    // 4. 部分 move：name 被搬走，pid 是 Copy 还能单独用。
    let moved = proc.name;
    println!("moved name: {moved}, pid still here: {}", proc.pid);
}

