// Day 8: enum 与模式匹配 —— 带数据的枚举 + match 穷尽性
enum Shape {
    Circle(f64),
    Rect { width: f64, height: f64 },
    Unit, // 不带数据的变体，和 C 的枚举值最像
}

impl Shape {
    fn area(&self) -> f64 {
        match self {
            Shape::Circle(r) => std::f64::consts::PI * r * r,
            Shape::Rect { width, height } => width * height,
            Shape::Unit => 0.0,
        }
    }

    fn describe(&self) -> String {
        match self {
            Shape::Circle(r) if *r > 10.0 => format!("大圆，半径 {r}"),
            Shape::Circle(r) => format!("小圆，半径 {r}"),
            Shape::Rect { width, height } => format!("矩形 {width} x {height}"),
            Shape::Unit => "单位图形".to_string(),
        }
    }
}

fn first_char(s: &str) -> Option<char> {
    s.chars().next()
}

fn main() {
    let shapes = vec![
        Shape::Circle(2.0),
        Shape::Rect { width: 3.0, height: 4.0 },
        Shape::Circle(20.0),
        Shape::Unit,
    ];
    for s in &shapes {
        println!("{}，面积 {:.2}", s.describe(), s.area());
    }

    // Option 的两种处理方式：match 穷尽，if let 只关心一种情况
    match first_char("rust") {
        Some(c) => println!("首字符是 {c}"),
        None => println!("空字符串"),
    }
    if let Some(c) = first_char("") {
        println!("首字符是 {c}");
    } else {
        println!("空字符串，没有首字符");
    }

    // match 的值也可以直接作为表达式结果
    let n = 2;
    let word = match n {
        0 => "零",
        1 => "一",
        2 => "二",
        _ => "很多",
    };
    println!("{n} 读作 {word}");
}

use std::collections::HashMap;

fn main() {
    let levels: Vec<String> = vec![
        "INFO".to_string(),
        "ERROR".to_string(),
        "INFO".to_string(),
    ];
    println!("第 0 个级别: {}", levels[0]);
    match levels.get(99) {
        Some(v) => println!("第 99 个级别: {v}"),
        None => println!("第 99 个级别不存在"),
    }
    let mut msg = String::from("启动");
    msg.push_str("完成");
    let summary = format!("{msg}, 共 {} 条级别记录", levels.len());
    println!("{summary}");
    let text = "你好 Rust";
    println!("\"{text}\" 的字节数是 {}, 字符数是 {}", text.len(), text.chars().count());
    let logs = [
        "INFO server started",
        "ERROR disk full",
        "INFO request ok",
        "WARN slow query",
        "ERROR disk full",
        "INFO request ok",
    ];
    let mut counts: HashMap<String, usize> = HashMap::new();
    let mut error_msgs: Vec<String> = Vec::new();
    for line in logs {
        let (level, rest) = line.split_once(' ').unwrap_or((line, ""));
        *counts.entry(level.to_string()).or_insert(0) += 1;
        if level == "ERROR" {
            error_msgs.push(rest.to_string());
        }
    }
    let mut keys: Vec<&String> = counts.keys().collect();
    keys.sort();
    for k in keys {
        println!("{k}: {}", counts[k]);
    }
    println!("ERROR 消息: {}", error_msgs.join(" | "));
    let total: usize = levels.iter().map(|s| s.len()).sum();
    println!("级别名总字节数: {total}");
    println!("仍可使用 levels, 长度 {}", levels.len());
}

