use std::error::Error;

fn level_of(line: &str) -> Option<&str> {
    line.split_whitespace().next()
}

fn code_of(line: &str) -> Result<u32, std::num::ParseIntError> {
    let code = line.split_whitespace().nth(2).unwrap_or("0");
    code.parse()
}

fn summarize(lines: &[&str]) -> Result<(usize, u32), Box<dyn Error>> {
    let mut errors = 0;
    let mut sum = 0;
    for line in lines {
        if level_of(line) == Some("ERROR") {
            errors += 1;
            sum += code_of(line)?;
        }
    }
    Ok((errors, sum))
}

fn main() -> Result<(), Box<dyn Error>> {
    let lines = [
        "INFO start 0",
        "ERROR disk 500",
        "WARN retry 0",
        "ERROR net 404",
    ];
    let (errors, sum) = summarize(&lines)?;
    println!("errors={errors} sum={sum}");
    println!("missing level: {:?}", level_of(""));
    println!("bad code: {:?}", code_of("ERROR x abc"));
    println!("ok code: {:?}", code_of("INFO ok 200"));
    Ok(())
}

use std::fmt::Display;

fn largest<T: PartialOrd>(list: &[T]) -> &T {
    let mut max = &list[0];
    for item in &list[1..] {
        if item > max { max = item; }
    }
    max
}

struct Stat<T> { name: &'static str, value: T }

impl<T: Display> Stat<T> {
    fn show(&self) { println!("{} = {}", self.name, self.value); }
}

trait Summarizable { fn summarize(&self) -> String; }

struct AccessLog { status: u32, path: String }
struct ErrorLog { code: u32, msg: String }

impl Summarizable for AccessLog {
    fn summarize(&self) -> String { format!("access {} {}", self.status, self.path) }
}

impl Summarizable for ErrorLog {
    fn summarize(&self) -> String { format!("error {} {}", self.code, self.msg) }
}

fn print_summary<T: Summarizable>(item: &T) { println!("{}", item.summarize()); }
fn print_summary_dyn(item: &dyn Summarizable) { println!("{}", item.summarize()); }

fn main() {
    let nums = [12, 7, 31, 5];
    println!("largest int: {}", largest(&nums));
    let chars = ['a', 'z', 'm'];
    println!("largest char: {}", largest(&chars));
    Stat { name: "errors", value: 3 }.show();
    Stat { name: "ratio", value: 0.75 }.show();
    let a = AccessLog { status: 200, path: "/api/logs".to_string() };
    let e = ErrorLog { code: 500, msg: "disk full".to_string() };
    print_summary(&a);
    print_summary(&e);
    print_summary_dyn(&a);
    print_summary_dyn(&e);
}

// Day 12: 生命周期 —— 读懂标注
// 标注只告诉编译器“引用之间有效期的关系”，不改变任何运行期行为。

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() >= y.len() { x } else { y }
}

struct LogEntry<'a> {
    level: &'a str,
    msg: &'a str,
}

impl<'a> LogEntry<'a> {
    fn show(&self) {
        println!("[{}] {}", self.level, self.msg);
    }
}

// 只有一个输入引用：省略规则自动把输出的生命周期绑到输入上，不用写 'a
fn first_word(s: &str) -> &str {
    match s.find(' ') {
        Some(i) => &s[..i],
        None => s,
    }
}

fn main() {
    let a = String::from("access log line");
    let b = String::from("err");
    println!("longest: {}", longest(&a, &b));

    let entry = LogEntry { level: "INFO", msg: "server started" };
    entry.show();

    let line = String::from("GET /api/logs HTTP/1.1");
    println!("first word: {}", first_word(&line));

    // 'static：字符串字面量在整个程序运行期都有效
    let s: &'static str = "startup complete";
    println!("static: {}", s);
}

