// 第 13 天 · 项目 1：日志分析 CLI —— clap + serde + anyhow
// 用法：cargo run -- --file sample.log
//       cargo run -- --file sample.log --level warn --format json
//       cargo run -- --file sample.log --config config.json

use anyhow::{Context, Result};
use clap::Parser;
use serde::Deserialize;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// 日志分析 CLI：按级别统计日志文件，并输出最常见的消息。
#[derive(Parser, Debug)]
#[command(version, about = "统计日志文件里各级别的条数")]
struct Args {
    /// 要分析的日志文件（每行形如 "2026-11-07T08:00:01Z INFO server started"）
    #[arg(long)]
    file: PathBuf,

    /// 只统计不低于该级别的日志：trace / debug / info / warn / error
    #[arg(long, default_value = "trace")]
    level: String,

    /// 输出格式：text 或 json
    #[arg(long, default_value = "text")]
    format: String,

    /// 可选的 JSON 配置文件，可覆盖 --level 与 --format
    #[arg(long)]
    config: Option<PathBuf>,
}

/// 配置文件结构（serde 直接从 JSON 反序列化）。
#[derive(Debug, Deserialize, Default)]
struct Config {
    min_level: Option<String>,
    format: Option<String>,
}

#[derive(Debug, Default)]
struct Stats {
    /// 各级别条数。
    by_level: HashMap<String, u64>,
    /// 各消息文本出现次数。
    by_message: HashMap<String, u64>,
    /// 低于阈值被跳过的行数。
    skipped: u64,
    /// 总行数。
    total: u64,
}

fn level_rank(level: &str) -> u8 {
    match level.to_ascii_lowercase().as_str() {
        "trace" => 0,
        "debug" => 1,
        "info" => 2,
        "warn" => 3,
        "error" => 4,
        _ => 0,
    }
}

/// 解析一行日志，返回 (级别, 消息)。格式不对返回 None。
fn parse_line(line: &str) -> Option<(&str, &str)> {
    let mut parts = line.splitn(3, ' ');
    let _ts = parts.next()?;
    let level = parts.next()?;
    let msg = parts.next()?;
    // 级别必须是已知级别之一，否则这行格式不对（比如 "garbage line ..."）
    if msg.is_empty()
        || !matches!(
            level.to_ascii_lowercase().as_str(),
            "trace" | "debug" | "info" | "warn" | "error"
        )
    {
        return None;
    }
    Some((level, msg))
}

fn analyze(path: &Path, min_level: &str) -> Result<Stats> {
    let text =
        fs::read_to_string(path).with_context(|| format!("无法读取日志文件 {}", path.display()))?;
    let mut stats = Stats::default();
    let threshold = level_rank(min_level);

    for line in text.lines() {
        stats.total += 1;
        let Some((level, msg)) = parse_line(line) else {
            stats.skipped += 1;
            continue;
        };
        if level_rank(level) < threshold {
            stats.skipped += 1;
            continue;
        }
        *stats.by_level.entry(level.to_string()).or_insert(0) += 1;
        *stats.by_message.entry(msg.to_string()).or_insert(0) += 1;
    }
    Ok(stats)
}

fn print_text(stats: &Stats, file: &Path) {
    println!(
        "文件：{}（共 {} 行，跳过 {} 行）",
        file.display(),
        stats.total,
        stats.skipped
    );
    println!("--- 按级别 ---");
    let mut levels: Vec<_> = stats.by_level.iter().collect();
    levels.sort_by_key(|(l, _)| level_rank(l));
    for (level, n) in levels {
        println!("{level:>6}: {n}");
    }
    println!("--- 出现最多的消息 ---");
    let mut msgs: Vec<_> = stats.by_message.iter().collect();
    msgs.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    for (msg, n) in msgs.iter().take(5) {
        println!("{n:>4} 次  {msg}");
    }
}

fn print_json(stats: &Stats) -> Result<()> {
    let out = serde_json::json!({
        "total": stats.total,
        "skipped": stats.skipped,
        "by_level": stats.by_level,
        "top_messages": stats.by_message.iter()
            .map(|(m, n)| serde_json::json!({"message": m, "count": n}))
            .collect::<Vec<_>>(),
    });
    println!("{}", serde_json::to_string_pretty(&out)?);
    Ok(())
}

fn run() -> Result<()> {
    let mut args = Args::parse();

    // 配置文件优先于命令行默认值：有配置就覆盖。
    if let Some(cfg_path) = &args.config {
        let raw = fs::read_to_string(cfg_path)
            .with_context(|| format!("配置文件 {}", cfg_path.display()))?;
        let cfg: Config = serde_json::from_str(&raw)
            .with_context(|| format!("配置文件 {} 不是合法 JSON", cfg_path.display()))?;
        if let Some(l) = cfg.min_level {
            args.level = l;
        }
        if let Some(f) = cfg.format {
            args.format = f;
        }
    }

    let stats = analyze(&args.file, &args.level)?;
    match args.format.as_str() {
        "json" => print_json(&stats)?,
        _ => print_text(&stats, &args.file),
    }
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        // anyhow 的 {:?} 会打印错误链：外层 context + 内层原因。
        eprintln!("错误：{e:?}");
        std::process::exit(1);
    }
}

/// 第 14 天 · 第二周复盘验收：enum、集合、错误处理、泛型、生命周期一次串起来。
use std::collections::HashMap;
use std::error::Error;
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum Level {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

impl Level {
    fn from_str(s: &str) -> Option<Level> {
        match s.to_ascii_lowercase().as_str() {
            "trace" => Some(Level::Trace),
            "debug" => Some(Level::Debug),
            "info" => Some(Level::Info),
            "warn" => Some(Level::Warn),
            "error" => Some(Level::Error),
            _ => None,
        }
    }
}

impl fmt::Display for Level {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self {
            Level::Trace => "TRACE",
            Level::Debug => "DEBUG",
            Level::Info => "INFO",
            Level::Warn => "WARN",
            Level::Error => "ERROR",
        };
        write!(f, "{name}")
    }
}

/// 一条解析后的日志：message 只借用原始文本，不复制。
#[derive(Debug)]
struct Entry<'a> {
    level: Level,
    message: &'a str,
}

/// 只有一个输入引用，省略规则自动把输出生命周期绑到输入上。
/// `'_` 是匿名生命周期：输出的借用和输入活得一样久。
fn parse_line(line: &str) -> Option<Entry<'_>> {
    let mut parts = line.splitn(3, ' ');
    let _ts = parts.next()?;
    let level = Level::from_str(parts.next()?)?;
    let message = parts.next()?;
    Some(Entry { level, message })
}

/// 泛型统计：对任意切片按 key 函数分组计数。
/// K 必须满足 Eq + Hash，否则 HashMap 没法用它当键。
fn count_by<T, K>(items: &[T], key: impl Fn(&T) -> K) -> HashMap<K, usize>
where
    K: Eq + std::hash::Hash,
{
    let mut map = HashMap::new();
    for item in items {
        *map.entry(key(item)).or_insert(0) += 1;
    }
    map
}

const SAMPLE: &str = "\
2026-11-08T09:00:01Z INFO server started
2026-11-08T09:00:02Z INFO request handled
2026-11-08T09:00:03Z WARN slow query
2026-11-08T09:00:04Z ERROR disk full
2026-11-08T09:00:05Z INFO request handled
garbage line
2026-11-08T09:00:06Z DEBUG cache hit
2026-11-08T09:00:07Z WARN slow query";

fn run() -> Result<(), Box<dyn Error>> {
    let entries: Vec<Entry> = SAMPLE.lines().filter_map(parse_line).collect();
    println!(
        "解析成功 {} 条（共 {} 行）",
        entries.len(),
        SAMPLE.lines().count()
    );

    // 按级别计数：HashMap 本身无序，想按级别顺序输出就按变体数组遍历。
    let by_level = count_by(&entries, |e| e.level);
    println!("--- 按级别 ---");
    for level in [
        Level::Trace,
        Level::Debug,
        Level::Info,
        Level::Warn,
        Level::Error,
    ] {
        let n = by_level.get(&level).copied().unwrap_or(0);
        println!("{level:>6}: {n}");
    }

    // 按消息计数：次数降序、消息升序，保证输出确定。
    let by_message = count_by(&entries, |e| e.message);
    let mut msgs: Vec<_> = by_message.iter().collect();
    msgs.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    println!("--- 出现最多的消息 ---");
    for (msg, n) in msgs {
        println!("{n:>4} 次  {msg}");
    }

    // 错误路径演示：Box<dyn Error> 也能用 ?，只不过没有 anyhow 的上下文链。
    match std::fs::read_to_string("no-such-file.txt") {
        Ok(_) => println!("意外：文件竟然存在"),
        Err(e) => println!("错误演示：读取 no-such-file.txt 失败：{e}"),
    }
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("错误：{e}");
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_line_ok_and_garbage() {
        let e = parse_line("2026-11-08T09:00:01Z INFO hello").unwrap();
        assert_eq!(e.level, Level::Info);
        assert_eq!(e.message, "hello");
        assert!(parse_line("garbage line").is_none());
        assert!(parse_line("2026-11-08T09:00:01Z FATAL boom").is_none());
    }

    #[test]
    fn count_by_groups_levels() {
        let entries: Vec<Entry> = SAMPLE.lines().filter_map(parse_line).collect();
        let by_level = count_by(&entries, |e| e.level);
        assert_eq!(by_level.get(&Level::Info).copied().unwrap_or(0), 3);
        assert_eq!(by_level.get(&Level::Warn).copied().unwrap_or(0), 2);
        assert_eq!(by_level.get(&Level::Trace).copied().unwrap_or(0), 0);
    }

    #[test]
    fn level_ordering_matches_severity() {
        assert!(Level::Error > Level::Warn);
        assert!(Level::Warn > Level::Info);
        assert!(Level::Info > Level::Debug);
    }
}

/// 第 15 天 · Box 智能指针：堆分配、递归类型与 trait 对象。
use std::fmt::Debug;

/// 递归类型必须用 Box 打断，否则编译器报 E0072（无限大小）。
#[derive(Debug)]
enum Expr {
    Num(i64),
    Add(Box<Expr>, Box<Expr>),
    Mul(Box<Expr>, Box<Expr>),
}

impl Expr {
    fn eval(&self) -> i64 {
        match self {
            Expr::Num(n) => *n,
            Expr::Add(a, b) => a.eval() + b.eval(),
            Expr::Mul(a, b) => a.eval() * b.eval(),
        }
    }

    fn depth(&self) -> usize {
        match self {
            Expr::Num(_) => 1,
            Expr::Add(a, b) | Expr::Mul(a, b) => 1 + a.depth().max(b.depth()),
        }
    }
}

/// trait 对象：Box<dyn Trait> 是「运行时才知道具体类型」的指针。
trait Shape: Debug {
    fn area(&self) -> f64;
    fn name(&self) -> &'static str;
}

#[derive(Debug)]
struct Circle {
    r: f64,
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.r * self.r
    }
    fn name(&self) -> &'static str {
        "圆"
    }
}

#[derive(Debug)]
struct Rect {
    w: f64,
    h: f64,
}

impl Shape for Rect {
    fn area(&self) -> f64 {
        self.w * self.h
    }
    fn name(&self) -> &'static str {
        "矩形"
    }
}

/// 大结构体：放进 Box 后 move 只搬指针，不搬数据。
#[derive(Debug)]
struct BigBuffer {
    data: [u8; 256 * 1024],
}

impl BigBuffer {
    fn new(fill: u8) -> Box<Self> {
        Box::new(Self {
            data: [fill; 256 * 1024],
        })
    }

    fn first(&self) -> u8 {
        self.data[0]
    }
}

fn main() {
    // 1. 递归表达式树：(2 + 3) * 4
    let expr = Expr::Mul(
        Box::new(Expr::Add(Box::new(Expr::Num(2)), Box::new(Expr::Num(3)))),
        Box::new(Expr::Num(4)),
    );
    println!("表达式：{expr:?}");
    println!("求值结果：{}（应为 20）", expr.eval());
    println!("树深：{}", expr.depth());

    // 2. Box 是独占所有权：move 只搬指针，旧变量失效。
    let boxed = Box::new(42_i32);
    println!(
        "Box 里的数据：{boxed}，Box 本身在栈上占 {} 字节",
        size_of_val(&boxed)
    );
    let moved = boxed;
    // println!("{boxed}"); // 编译错误 E0382：boxed 已被 move
    println!("move 之后：{moved}");

    // 3. 大结构体放进 Box：move 成本是 8 字节指针，不是 256KB 数据。
    let big = BigBuffer::new(7);
    println!(
        "大缓冲区首字节：{}，Box 占 {} 字节",
        big.first(),
        size_of_val(&big)
    );
    let big2 = big; // 只搬指针
    println!("move 后首字节仍为：{}", big2.first());

    // 4. Box<dyn Trait>：不同类型装进同一个 Vec，运行时分发。
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Circle { r: 2.0 }),
        Box::new(Rect { w: 3.0, h: 4.0 }),
        Box::new(Circle { r: 1.0 }),
    ];
    let mut total = 0.0;
    for s in &shapes {
        println!("{} 的面积：{:.2}", s.name(), s.area());
        total += s.area();
    }
    println!("总面积：{total:.2}");

    // 5. 解引用与 Deref 强制转换：&Box<T> 能当 &T 用。
    let name_box = Box::new(String::from("hello"));
    let name_ref: &str = &name_box; // Deref 强制转换：&Box<String> -> &String -> &str
    println!("解引用：{}，长度：{}", *name_box, name_ref.len());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn expr_eval_and_depth() {
        let expr = Expr::Mul(
            Box::new(Expr::Add(Box::new(Expr::Num(2)), Box::new(Expr::Num(3)))),
            Box::new(Expr::Num(4)),
        );
        assert_eq!(expr.eval(), 20);
        assert_eq!(expr.depth(), 3);
        assert_eq!(Expr::Num(7).eval(), 7);
        assert_eq!(Expr::Num(7).depth(), 1);
    }

    #[test]
    fn big_buffer_moves_only_pointer() {
        let big = BigBuffer::new(9);
        assert_eq!(big.first(), 9);
        assert_eq!(size_of_val(&big), size_of::<usize>());
        let big2 = big;
        assert_eq!(big2.first(), 9);
    }

    #[test]
    fn trait_object_dispatch() {
        let shapes: Vec<Box<dyn Shape>> = vec![
            Box::new(Circle { r: 1.0 }),
            Box::new(Rect { w: 2.0, h: 3.0 }),
        ];
        assert_eq!(shapes[0].name(), "圆");
        assert_eq!(shapes[1].name(), "矩形");
        let total: f64 = shapes.iter().map(|s| s.area()).sum();
        assert!((total - (std::f64::consts::PI + 6.0)).abs() < 1e-9);
    }

    #[test]
    fn deref_coercion_works() {
        let name_box = Box::new(String::from("hello"));
        let name_ref: &str = &name_box;
        assert_eq!(name_ref.len(), 5);
        assert_eq!(*name_box, "hello");
    }
}

/// 第 16 天 · Rc 与 RefCell：单线程共享所有权与内部可变性。
use std::cell::RefCell;
use std::rc::{Rc, Weak};

/// 多处共享的只读配置：Rc 只加引用计数，不复制数据。
#[derive(Debug)]
struct Config {
    name: String,
    max_connections: usize,
}

impl Config {
    fn describe(&self) -> String {
        format!("{}（最大连接数 {}）", self.name, self.max_connections)
    }
}

/// 共享的可变计数器：Rc 管共享，RefCell 管可变。
#[derive(Debug)]
struct Counter {
    value: u32,
}

/// 树节点：子节点用 Rc 强引用，父节点用 Weak 弱引用，避免循环。
#[derive(Debug)]
struct Node {
    name: &'static str,
    children: Vec<Rc<RefCell<Node>>>,
    parent: Weak<RefCell<Node>>,
}

impl Node {
    fn new(name: &'static str) -> Rc<RefCell<Node>> {
        Rc::new(RefCell::new(Node {
            name,
            children: Vec::new(),
            parent: Weak::new(),
        }))
    }

    fn add_child(parent: &Rc<RefCell<Node>>, child: &Rc<RefCell<Node>>) {
        child.borrow_mut().parent = Rc::downgrade(parent);
        parent.borrow_mut().children.push(Rc::clone(child));
    }
}

fn main() {
    // 1. Rc 共享所有权：clone 只加引用计数，不复制数据。
    let cfg = Rc::new(Config {
        name: "sandbox-gateway".to_string(),
        max_connections: 128,
    });
    println!("配置：{}", cfg.describe());
    println!("创建后引用计数：{}", Rc::strong_count(&cfg));
    let cfg_a = Rc::clone(&cfg);
    let cfg_b = Rc::clone(&cfg);
    println!("两次 clone 后引用计数：{}", Rc::strong_count(&cfg));
    println!(
        "三处看到的是同一份配置：{} / {} / {}",
        cfg.describe(),
        cfg_a.describe(),
        cfg_b.describe()
    );
    drop(cfg_a);
    println!("drop 一份后引用计数：{}", Rc::strong_count(&cfg));
    drop(cfg_b);
    println!("再 drop 一份后引用计数：{}", Rc::strong_count(&cfg));

    // 2. Rc<RefCell<T>>：多处持有，处处可改。
    let counter = Rc::new(RefCell::new(Counter { value: 0 }));
    let worker_a = Rc::clone(&counter);
    let worker_b = Rc::clone(&counter);
    worker_a.borrow_mut().value += 1;
    worker_b.borrow_mut().value += 10;
    counter.borrow_mut().value += 100;
    println!("共享计数器最终值：{}（应为 111）", counter.borrow().value);
    println!("计数器引用计数：{}", Rc::strong_count(&counter));

    // 3. 运行时借用检查：已有可变借用时，第二次可变借用被拒绝。
    let cell = RefCell::new(5_i32);
    let _guard = cell.borrow_mut(); // 可变借用还活着
    match cell.try_borrow_mut() {
        Ok(_) => println!("意外：第二次可变借用居然成功了"),
        Err(e) => println!("第二次可变借用被拒绝：{e}"),
    }
    drop(_guard);
    *cell.borrow_mut() = 6;
    println!("释放后可变借用恢复：{}", cell.borrow());

    // 4. Weak 打破循环引用：父节点持有子节点，子节点只弱引用父节点。
    let root = Node::new("root");
    let child = Node::new("child");
    Node::add_child(&root, &child);
    println!(
        "挂接后：root 引用计数 {}，child 引用计数 {}",
        Rc::strong_count(&root),
        Rc::strong_count(&child)
    );
    println!(
        "child 能找到父节点：{}",
        child
            .borrow()
            .parent
            .upgrade()
            .map(|p| p.borrow().name)
            .unwrap_or("（已释放）")
    );
    drop(root);
    println!(
        "drop root 后，child 的父节点：{}",
        child
            .borrow()
            .parent
            .upgrade()
            .map(|p| p.borrow().name)
            .unwrap_or("（已释放）")
    );

    // 5. 反面教材：两个节点互相强引用，drop 外层句柄后谁也释放不了。
    let a = Rc::new(RefCell::new(Node {
        name: "a",
        children: Vec::new(),
        parent: Weak::new(),
    }));
    let b = Rc::new(RefCell::new(Node {
        name: "b",
        children: Vec::new(),
        parent: Weak::new(),
    }));
    a.borrow_mut().children.push(Rc::clone(&b));
    b.borrow_mut().children.push(Rc::clone(&a));
    println!(
        "互相强引用后：a 引用计数 {}，b 引用计数 {}",
        Rc::strong_count(&a),
        Rc::strong_count(&b)
    );
    drop(a);
    drop(b);
    println!("drop 外层句柄后，两节点的引用计数仍为 1（互相拖着，谁也释放不了）");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rc_clone_shares_not_copies() {
        let shared = Rc::new(RefCell::new(0_u32));
        let h1 = Rc::clone(&shared);
        let h2 = Rc::clone(&shared);
        assert_eq!(Rc::strong_count(&shared), 3);
        *h1.borrow_mut() = 42;
        assert_eq!(*h2.borrow(), 42);
        assert_eq!(*shared.borrow(), 42);
        drop(h1);
        drop(h2);
        assert_eq!(Rc::strong_count(&shared), 1);
    }

    #[test]
    fn refcell_runtime_borrow_check() {
        let cell = RefCell::new(5_i32);
        let guard = cell.borrow_mut();
        assert!(cell.try_borrow().is_err());
        assert!(cell.try_borrow_mut().is_err());
        drop(guard);
        assert_eq!(*cell.borrow(), 5);
        *cell.borrow_mut() = 6;
        assert_eq!(*cell.borrow(), 6);
    }

    #[test]
    fn weak_breaks_cycle() {
        let root = Node::new("root");
        let child = Node::new("child");
        Node::add_child(&root, &child);
        assert_eq!(Rc::strong_count(&root), 1);
        assert_eq!(Rc::strong_count(&child), 2);
        assert!(child.borrow().parent.upgrade().is_some());
        drop(root);
        assert_eq!(Rc::strong_count(&child), 1);
        assert!(child.borrow().parent.upgrade().is_none());
    }

    #[test]
    fn strong_cycle_never_drops() {
        let a = Rc::new(RefCell::new(Node {
            name: "a",
            children: Vec::new(),
            parent: Weak::new(),
        }));
        let b = Rc::new(RefCell::new(Node {
            name: "b",
            children: Vec::new(),
            parent: Weak::new(),
        }));
        a.borrow_mut().children.push(Rc::clone(&b));
        b.borrow_mut().children.push(Rc::clone(&a));
        assert_eq!(Rc::strong_count(&a), 2);
        assert_eq!(Rc::strong_count(&b), 2);
        drop(a);
        drop(b);
        // 两个节点互相拖着，引用计数永远回不到 0：这就是循环引用泄漏。
        // 注意：这里故意让它们泄漏，测试本身只验证计数行为。
    }

    #[test]
    fn shared_counter_accumulates() {
        let counter = Rc::new(RefCell::new(Counter { value: 0 }));
        let workers: Vec<_> = (0..3).map(|_| Rc::clone(&counter)).collect();
        for (i, w) in workers.iter().enumerate() {
            w.borrow_mut().value += (i + 1) as u32;
        }
        assert_eq!(counter.borrow().value, 6);
    }
}

/// 第 17 天 · Arc 与 Mutex：多线程共享所有权。
use std::sync::{Arc, Mutex};
use std::thread;

/// 多线程共享的只读配置：Arc 只加引用计数，不复制数据。
#[derive(Debug)]
struct Config {
    name: &'static str,
    max_connections: usize,
}

fn main() {
    // 1. Arc 共享只读配置：多个线程各持一份，计数归零才释放。
    let cfg = Arc::new(Config {
        name: "sandbox-gateway",
        max_connections: 128,
    });
    println!("配置：{}（最大连接数 {}）", cfg.name, cfg.max_connections);
    println!("创建后引用计数：{}", Arc::strong_count(&cfg));
    let mut handles = vec![];
    for i in 0..4 {
        let c = Arc::clone(&cfg);
        handles.push(thread::spawn(move || {
            println!(
                "线程 {} 看到的配置：{}（最大连接数 {}）",
                i, c.name, c.max_connections
            );
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    println!("线程结束后引用计数：{}", Arc::strong_count(&cfg));

    // 2. Arc<Mutex<T>>：多线程共享的可变计数器，8 个线程各加 1000 次。
    let counter = Arc::new(Mutex::new(0_u32));
    let mut handles = vec![];
    for i in 0..8 {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..1000 {
                *c.lock().unwrap() += 1;
            }
            println!("线程 {} 完成 1000 次累加", i);
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    println!(
        "共享计数器最终值：{}（应为 8000）",
        *counter.lock().unwrap()
    );
    println!("计数器引用计数：{}", Arc::strong_count(&counter));

    // 3. try_lock：拿不到锁时不阻塞，返回 Err。
    let m = Mutex::new(0_u32);
    let _guard = m.lock().unwrap(); // 锁还被拿着
    match m.try_lock() {
        Ok(_) => println!("意外：try_lock 居然成功了"),
        Err(e) => println!("try_lock 被拒绝：{e}"),
    }
    drop(_guard);
    *m.lock().unwrap() = 42;
    println!("释放后可正常加锁，值：{}", *m.lock().unwrap());

    // 4. 锁中毒与恢复：持有锁的线程 panic，锁中毒但数据仍在。
    let poisoned = Arc::new(Mutex::new(100_u32));
    let p = Arc::clone(&poisoned);
    let h = thread::spawn(move || {
        let mut g = p.lock().unwrap();
        *g += 1;
        panic!("模拟持有锁的线程崩溃");
    });
    let _ = h.join();
    match poisoned.lock() {
        Ok(g) => println!("未中毒，值：{g}"),
        Err(e) => println!(
            "锁已中毒，仍可取回数据：{}（中毒前的值已被保留）",
            *e.into_inner()
        ),
    }
}

/// 第 18 天 · RwLock：读多写少的读写锁。
use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::thread;
use std::time::Duration;

/// 网关用的只读配置表：读多写少，典型 RwLock 场景。
#[derive(Debug)]
struct Config {
    routes: HashMap<&'static str, &'static str>,
    version: u64,
}

fn main() {
    // 1. Arc<RwLock<Config>>：多个读线程并行读，写线程独占改。
    let cfg = Arc::new(RwLock::new(Config {
        routes: HashMap::from([
            ("api.example.com", "10.0.0.1:8080"),
            ("cdn.example.com", "10.0.0.2:8080"),
        ]),
        version: 1,
    }));

    // 4 个读线程：同时拿读锁，谁也不用等谁。
    let mut handles = vec![];
    for i in 0..4 {
        let c = Arc::clone(&cfg);
        handles.push(thread::spawn(move || {
            let g = c.read().unwrap();
            println!(
                "读线程 {}：版本 {}，api.example.com -> {}",
                i, g.version, g.routes["api.example.com"]
            );
            // 读锁持有期间睡一会儿：证明多个读锁确实能共存，
            // 若换成 Mutex，4 个读线程就要排队。
            thread::sleep(Duration::from_millis(50));
        }));
    }

    // 1 个写线程：拿写锁要等所有读锁释放，写期间读也要等。
    let c = Arc::clone(&cfg);
    let writer = thread::spawn(move || {
        thread::sleep(Duration::from_millis(10));
        let mut g = c.write().unwrap();
        g.routes.insert("new.example.com", "10.0.0.3:8080");
        g.version += 1;
        println!("写线程：已更新配置到版本 {}", g.version);
    });

    for h in handles {
        h.join().unwrap();
    }
    writer.join().unwrap();
    let g = cfg.read().unwrap();
    println!("最终：版本 {}，共 {} 条路由", g.version, g.routes.len());
    drop(g);

    // 2. try_read / try_write：拿不到就立刻返回 Err，不阻塞。
    let lock = RwLock::new(0_u32);
    let _w = lock.write().unwrap(); // 写锁被占着
    match lock.try_read() {
        Ok(_) => println!("意外：写锁被占时 try_read 居然成功了"),
        Err(e) => println!("写锁被占时 try_read 被拒绝：{e}"),
    }
    match lock.try_write() {
        Ok(_) => println!("意外：写锁被占时 try_write 居然成功了"),
        Err(e) => println!("写锁被占时 try_write 被拒绝：{e}"),
    }
    drop(_w);
    assert_eq!(*lock.read().unwrap(), 0);

    // 3. 读锁不能原地升级成写锁：拿着读锁再 try_write 会失败，
    // 若用 write() 会死锁（自己等自己）。正确做法是先 drop 读锁。
    let lock = RwLock::new(10_u32);
    {
        let r = lock.read().unwrap();
        println!("持有读锁，值：{r}");
        match lock.try_write() {
            Ok(_) => println!("意外：读锁被占时 try_write 居然成功了"),
            Err(e) => println!("读锁被占时 try_write 被拒绝：{e}（升级必须先放读锁）"),
        }
    } // 读锁在这里释放
    *lock.write().unwrap() = 20;
    println!("放掉读锁后拿到写锁，值改为：{}", *lock.read().unwrap());

    // 4. 写锁中毒与恢复：持写锁的线程 panic，之后读/写都返回 Err，
    // into_inner() 可取回数据。
    let poisoned = Arc::new(RwLock::new(100_u32));
    let p = Arc::clone(&poisoned);
    let h = thread::spawn(move || {
        let mut g = p.write().unwrap();
        *g += 1;
        panic!("模拟持写锁的线程崩溃");
    });
    let _ = h.join();
    let res = poisoned.read();
    match res {
        Ok(g) => println!("未中毒，值：{g}"),
        Err(e) => println!("读锁发现中毒，仍可取回数据：{}", *e.into_inner()),
    }
}

