        // Arc<RwLock<T>> 可以 move 进线程；但读/写守卫本身不是 Send
        // （已实测：把 RwLockReadGuard 传给 assert_send 会报 E0277），
        // 锁是谁拿的、就由谁在同一个线程里释放。
        fn assert_send<T: Send>(_: T) {}
        let shared = Arc::new(RwLock::new(0_u32));
        assert_send(shared);
