use std::sync::Arc;
/// 第 19 天 · Send、Sync 与 channel：把数据安全地送进线程。
use std::sync::mpsc;
use std::thread;

/// 1..=1000 的分段求和：4 个 worker 各算一段，结果经 channel 回传主线程聚合。
/// 对照 C++：这相当于 4 个 std::thread 各算一段、通过队列把结果发回主线程；
/// 区别在 Rust 这里：channel 的发送端 `Sender<T>` 要求 T: Send，`Rc` 这样
/// 的类型连编译都过不了——数据竞争在编译期就被拦住，而不是跑起来再崩。
fn main() {
    // 1. mpsc：多生产者、单消费者。tx 可以 clone 多份，rx 只有一份。
    let (tx, rx) = mpsc::channel::<(usize, u64)>();

    let n_workers = 4;
    let total: u64 = 1000;
    let chunk = total / n_workers as u64;

    let mut handles = vec![];
    for id in 0..n_workers {
        let tx = tx.clone(); // 每个 worker 一份发送端
        let start = id as u64 * chunk + 1;
        let end = if id == n_workers - 1 {
            total
        } else {
            (id as u64 + 1) * chunk
        };
        handles.push(thread::spawn(move || {
            let partial: u64 = (start..=end).sum();
            // send 会 move 走 partial：发出去的东西，发送方就不能再用了。
            tx.send((id, partial)).expect("接收端不应提前关闭");
            println!("worker {id}：算出 {start}..={end} 的和 = {partial}");
        }));
    }
    drop(tx); // 丢掉主线程手里这份 tx：所有 worker 结束后 channel 才会关闭，

    // 2. 把 rx 当迭代器用：收到 4 条结果后 channel 关闭，循环自然结束。
    let mut sum = 0_u64;
    for (id, partial) in rx {
        println!("主线程收到 worker {id} 的结果：{partial}");
        sum += partial;
    }
    for h in handles {
        h.join().unwrap();
    }
    println!("1..=1000 的总和 = {sum}");
    assert_eq!(sum, 500_500);

    // 3. 接收端已关闭时 send 返回 Err：别 unwrap，要处理。
    let (tx2, rx2) = mpsc::channel::<u32>();
    drop(rx2); // 接收端先走
    match tx2.send(42) {
        Ok(()) => println!("意外：接收端已关闭，send 居然成功了"),
        Err(e) => println!("接收端已关闭，send 被拒绝，丢掉的值是：{}", e.0),
    }

    // 4. Send / Sync 自查：能通过编译，就是类型系统给出的保证。
    fn assert_send<T: Send>(_: T) {}
    fn assert_sync<T: Sync>(_: T) {}
    assert_send(Arc::new(std::sync::Mutex::new(0_u32)));
    assert_sync(Arc::new(std::sync::Mutex::new(0_u32)));
    assert_send(mpsc::channel::<u32>().0); // Sender<u32> 是 Send
    assert_sync(std::sync::Mutex::new(0_u32));
    println!("Send / Sync 自查通过：Arc<Mutex<u32>> 既是 Send 也是 Sync");
}

