//! 第 20 天 · 项目 2 实操：多线程文件哈希器。
//!
//! 主线程经任务 channel 把文件路径分发给 N 个 worker，
//! 每个 worker 读文件、算哈希，再经结果 channel 把结果发回主线程聚合，
//! 最后与单线程版逐项比对、打印耗时与加速比。
//! 零外部依赖：哈希用标准库的 DefaultHasher（SipHash），
//! 不是密码学哈希，换 sha2 crate 只需改 `hash_file` 一处。

use std::collections::hash_map::DefaultHasher;
use std::fs;
use std::hash::{Hash, Hasher};
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, mpsc};
use std::thread;
use std::time::Instant;

/// 对单个文件算哈希：按 8 KiB 分块读，边读边喂给 DefaultHasher。
/// 分块读而不是 `fs::read` 整文件进内存——大文件也不会把内存撑爆。
fn hash_file(path: &Path) -> io::Result<u64> {
    let mut file = fs::File::open(path)?;
    let mut hasher = DefaultHasher::new();
    let mut buf = [0_u8; 8192];
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        buf[..n].hash(&mut hasher);
    }
    Ok(hasher.finish())
}

/// 生成测试文件：每个文件 `file_bytes` 字节，内容由文件编号做种子、
/// 用 xorshift 生成的确定性伪随机字节——每次运行内容相同，哈希可复现。
fn make_test_files(dir: &Path, n_files: usize, file_bytes: usize) -> io::Result<Vec<PathBuf>> {
    fs::create_dir_all(dir)?;
    let mut paths = Vec::with_capacity(n_files);
    for i in 0..n_files {
        let path = dir.join(format!("file-{i:03}.bin"));
        let mut data = Vec::with_capacity(file_bytes);
        let mut x: u64 = 0x9E37_79B9_7F4A_7C15u64.wrapping_add(i as u64);
        while data.len() < file_bytes {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            data.extend_from_slice(&x.to_le_bytes());
        }
        data.truncate(file_bytes);
        fs::write(&path, &data)?;
        paths.push(path);
    }
    Ok(paths)
}

/// 单线程版：顺序算每个文件的哈希。
fn hash_single_thread(paths: &[PathBuf]) -> io::Result<Vec<(PathBuf, u64)>> {
    let mut out = Vec::with_capacity(paths.len());
    for p in paths {
        out.push((p.clone(), hash_file(p)?));
    }
    Ok(out)
}

/// 多线程版：任务 channel 分发路径，结果 channel 回传哈希。
/// mpsc 的 Receiver 只有一份、不能 clone，所以用 `Arc<Mutex<Receiver>>`
/// 让多个 worker 轮流取任务——这是标准库里实现「多消费者」的标准写法，
/// 代价是取任务时要抢一把小锁；真正的多消费者 channel 在 crossbeam 里。
fn hash_multi_thread(paths: &[PathBuf], n_workers: usize) -> io::Result<Vec<(PathBuf, u64)>> {
    let (task_tx, task_rx) = mpsc::channel::<PathBuf>();
    let (result_tx, result_rx) = mpsc::channel::<(PathBuf, io::Result<u64>)>();
    let task_rx = Arc::new(Mutex::new(task_rx));

    let mut handles = Vec::with_capacity(n_workers);
    for _ in 0..n_workers {
        let task_rx = Arc::clone(&task_rx);
        let result_tx = result_tx.clone();
        handles.push(thread::spawn(move || {
            loop {
                let task = {
                    let rx = task_rx.lock().unwrap();
                    rx.recv()
                };
                match task {
                    Ok(path) => {
                        let r = hash_file(&path);
                        // 接收端若已关闭，send 失败也无所谓：直接丢掉，不 panic。
                        let _ = result_tx.send((path, r));
                    }
                    Err(_) => break, // 任务 channel 关闭：没有更多任务，退出。
                }
            }
        }));
    }
    drop(result_tx); // 主线程这份 result_tx 也要丢掉，否则结果收不完。

    for p in paths {
        task_tx.send(p.clone()).unwrap();
    }
    drop(task_tx); // 发完任务就关闭 channel：worker 取完任务就退出。

    let mut out = Vec::with_capacity(paths.len());
    for (path, r) in result_rx {
        out.push((path, r?));
    }
    for h in handles {
        h.join().unwrap();
    }
    Ok(out)
}

fn main() -> io::Result<()> {
    let n_workers = thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);
    println!("本机可用并行度：{n_workers} 个线程");

    let dir = std::env::temp_dir().join("rust-day20-hash-bench");
    let n_files = 64;
    let file_bytes = 1024 * 1024;
    let paths = make_test_files(&dir, n_files, file_bytes)?;
    println!("已生成 {n_files} 个测试文件，每个 {file_bytes} 字节");

    let t0 = Instant::now();
    let single = hash_single_thread(&paths)?;
    let single_elapsed = t0.elapsed();

    let t0 = Instant::now();
    let mut multi = hash_multi_thread(&paths, n_workers)?;
    let multi_elapsed = t0.elapsed();

    // 结果必须一致：按路径排序后逐项比较，顺序不同不算错。
    let mut single_sorted = single.clone();
    single_sorted.sort();
    multi.sort();
    assert_eq!(single_sorted, multi, "单线程与多线程的哈希结果必须一致");

    println!("单线程：{single_elapsed:?}，多线程（{n_workers} worker）：{multi_elapsed:?}");
    let speedup = single_elapsed.as_secs_f64() / multi_elapsed.as_secs_f64();
    println!("加速比：{speedup:.2}x");
    println!(
        "示例：{} -> {:#018x}",
        single_sorted[0].0.display(),
        single_sorted[0].1
    );

    fs::remove_dir_all(&dir)?; // 清理测试数据。
    Ok(())
}

