        let paths = make_test_files(&dir, 3, 4096).unwrap();
        let h1 = hash_file(&paths[0]).unwrap();
        let h2 = hash_file(&paths[0]).unwrap();
        assert_eq!(h1, h2, "同一文件两次哈希必须相同");
        assert_ne!(h1, hash_file(&paths[1]).unwrap(), "不同文件哈希应不同");
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn empty_file_hashes_without_error() {
        let dir = tmp_dir("empty");
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let empty = dir.join("empty.bin");
        fs::write(&empty, []).unwrap();
        assert!(hash_file(&empty).is_ok());
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn single_and_multi_thread_agree() {
        let dir = tmp_dir("agree");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 12, 8192).unwrap();
        let mut single = hash_single_thread(&paths).unwrap();
        let mut multi = hash_multi_thread(&paths, 4).unwrap();
        single.sort();
        multi.sort();
        assert_eq!(single, multi);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn more_workers_than_files_still_works() {
        let dir = tmp_dir("many-workers");
        let _ = fs::remove_dir_all(&dir);
        let paths = make_test_files(&dir, 2, 4096).unwrap();
        let mut out = hash_multi_thread(&paths, 8).unwrap();
        assert_eq!(out.len(), 2);
        out.sort();
        let mut single = hash_single_thread(&paths).unwrap();
        single.sort();
        assert_eq!(out, single);
        fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn missing_file_returns_error() {
        let missing = PathBuf::from("/tmp/rust-day20-no-such-file.bin");
        assert!(hash_file(&missing).is_err());
        let paths = vec![missing];
        assert!(hash_single_thread(&paths).is_err());
    }
}
